QUESTIONS = [{'q': 'Choose the word that is nearest in meaning (synonym) to the underlined word:\\nThe manager gave a METICULOUS explanation of the new financial policy.', 'a': 'Painstaking and thorough', 'b': 'Careless and hurried', 'c': 'Ambiguous and vague', 'd': 'Brief and informal', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Meticulous' means showing great attention to detail; very careful and precise.", 'diff': 'EASY'}, {'q': 'Choose the word opposite in meaning (antonym) to the underlined word:\\nThe minister was applauded for his CANDID assessment of the economic situation.', 'a': 'Deceptive and evasive', 'b': 'Honest and frank', 'c': 'Eloquent and loud', 'd': 'Courageous and clear', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Candid' means truthful and straightforward; its opposite is deceptive or evasive.", 'diff': 'MEDIUM'}, {'q': 'Choose the correct option to fill the gap:\\nNeither the teacher nor the students present at the meeting yesterday.', 'a': 'were', 'b': 'was', 'c': 'are', 'd': 'is', 'ans': 'A', 'topic': 'Concord & Grammar', 'exp': "With 'neither... nor', the verb agrees with the nearer subject ('the students' is plural => were).", 'diff': 'MEDIUM'}, {'q': 'Choose the correct option to fill the gap:\\nThe committee submitted report to the governing council this morning.', 'a': 'its', 'b': "it's", 'c': 'their', 'd': 'there', 'ans': 'A', 'topic': 'Concord & Grammar', 'exp': "'Committee' acting as a collective unit takes the singular possessive pronoun 'its'.", 'diff': 'EASY'}, {'q': 'Choose the correct option to complete the conditional sentence:\\nIf she hard, she would have passed the examination.', 'a': 'had studied', 'b': 'studied', 'c': 'has studied', 'd': 'studies', 'ans': 'A', 'topic': 'Grammar & Tenses', 'exp': "Past counterfactual conditional (Third conditional) requires 'had + past participle' in the if-clause.", 'diff': 'MEDIUM'}, {'q': "Identify the figure of speech in the expression: 'The angry waves swallowed the small fishing boat.'", 'a': 'Personification', 'b': 'Hyperbole', 'c': 'Metaphor', 'd': 'Simile', 'ans': 'A', 'topic': 'Literary Appreciation', 'exp': "Attributing human traits ('angry', 'swallowed') to inanimate sea waves is personification.", 'diff': 'MEDIUM'}, {'q': 'Choose the word with the same vowel sound as the one in bold: b**ir**d /ɜː/', 'a': 'Word', 'b': 'Board', 'c': 'Bread', 'd': 'Beard', 'ans': 'A', 'topic': 'Oral English & Phonetics', 'exp': "'Bird' and 'word' both contain the central long vowel /ɜː/.", 'diff': 'EASY'}, {'q': 'Choose the word that has the same consonant sound as the underlined letter: **ph**ilosophy', 'a': 'Fame', 'b': 'Vine', 'c': 'Pint', 'd': 'Pine', 'ans': 'A', 'topic': 'Oral English & Phonetics', 'exp': "'ph' in philosophy represents the voiceless labiodental fricative /f/, as in 'fame'.", 'diff': 'MEDIUM'}, {'q': "Choose the option that best explains the idiom:\\n'The new clerk decided to **let the cat out of the bag**.'", 'a': 'Revealed a secret unintentionally', 'b': 'Bought a pet cat', 'c': 'Refused to work diligently', 'd': 'Dismissed the complaint', 'ans': 'A', 'topic': 'Idiomatic Expressions', 'exp': "To 'let the cat out of the bag' means to reveal confidential information, often unintentionally.", 'diff': 'MEDIUM'}, {'q': 'Choose the correct preposition:\\nThe young scholar was acquitted the charges of examination malpractice.', 'a': 'of', 'b': 'from', 'c': 'with', 'd': 'for', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The standard prepositional collocation with 'acquit' is 'acquit someone of an offense'.", 'diff': 'EASY'}, {'q': 'Choose the word with the primary stress on the first syllable:', 'a': 'COMFORTABLE', 'b': 'PROVINCIAL', 'c': 'DETERMINISTIC', 'd': 'PRECISE', 'ans': 'A', 'topic': 'Oral English & Stress', 'exp': "'COM-for-ta-ble' carries primary stress on the initial syllable.", 'diff': 'MEDIUM'}, {'q': 'Choose the option that correctly completes the tag question:\\nYou have not seen the principal today, ?', 'a': 'have you', 'b': "haven't you", 'c': 'did you', 'd': "didn't you", 'ans': 'A', 'topic': 'Question Tags', 'exp': "A negative statement takes an affirmative tag: 'have not seen' => 'have you?'.", 'diff': 'MEDIUM'}, {'q': 'Choose the word opposite in meaning to EPHEMERAL:', 'a': 'Permanent', 'b': 'Fleeting', 'c': 'Short-lived', 'd': 'Transient', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Ephemeral' means lasting for a very short time; its antonym is 'permanent'.", 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to EXONERATE:', 'a': 'Absolve', 'b': 'Implicate', 'c': 'Accuse', 'd': 'Condemn', 'ans': 'A', 'topic': 'Synonyms', 'exp': 'To exonerate is to officially declare someone not guilty or blame-free (absolve).', 'diff': 'MEDIUM'}, {'q': 'Choose the correct modal auxiliary:\\nYou finish the assignment before the deadline tomorrow; it is mandatory.', 'a': 'must', 'b': 'might', 'c': 'could', 'd': 'would', 'ans': 'A', 'topic': 'Grammar & Modals', 'exp': "'Must' expresses mandatory obligation.", 'diff': 'MEDIUM'}, {'q': 'Select the correctly punctuated sentence:', 'a': 'Although he was exhausted, he completed the project on time.', 'b': 'Although he was exhausted he completed, the project on time.', 'c': 'Although, he was exhausted he completed the project on time.', 'd': 'Although he was exhausted; he completed the project on time.', 'ans': 'A', 'topic': 'Punctuation', 'exp': 'A subordinate clause at the beginning of a sentence is set off by a comma.', 'diff': 'EASY'}, {'q': 'Choose the word that has a different stress pattern from the others:', 'a': 'Democracy (2nd syllable)', 'b': 'Education (3rd syllable)', 'c': 'Information (3rd syllable)', 'd': 'Celebration (3rd syllable)', 'ans': 'A', 'topic': 'Oral English & Stress', 'exp': 'Democracy is stressed on the 2nd syllable (de-MOC-ra-cy); the others are on the 3rd syllable.', 'diff': 'MEDIUM'}, {'q': 'Choose the correct spelling:', 'a': 'Accommodate', 'b': 'Acommodate', 'c': 'Accomodate', 'd': 'Acomodate', 'ans': 'A', 'topic': 'Spelling', 'exp': "Accommodate is spelled with double 'c' and double 'm'.", 'diff': 'MEDIUM'}, {'q': 'Choose the correct form:\\nTen kilometres too far to walk on foot in this heat.', 'a': 'is', 'b': 'are', 'c': 'were', 'd': 'have been', 'ans': 'A', 'topic': 'Concord & Grammar', 'exp': 'Expressions of distance, time, and money viewed as a single unit take singular verbs.', 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to UBIQUITOUS:', 'a': 'Omnipresent', 'b': 'Scarce', 'c': 'Unique', 'd': 'Ancient', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Ubiquitous' means present, appearing, or found everywhere (omnipresent).", 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: ABHOR.', 'a': 'Detest intensely', 'b': 'Admire deeply', 'c': 'Forgive', 'd': 'Tolerate', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'To abhor means to regard with extreme repugnance or hatred.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: AMELIORATE.', 'a': 'Make better or improve', 'b': 'Worsen severely', 'c': 'Destroy completely', 'd': 'Halt', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'To ameliorate is to make a bad situation more bearable or better.', 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to the capitalized word: ANOMALY.', 'a': 'Deviation from the norm or irregularity', 'b': 'Standard occurrence', 'c': 'Legal precedent', 'd': 'Symmetry', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'An anomaly is something that deviates from what is standard, normal, or expected.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: AUDACIOUS.', 'a': 'Showing a willing daring boldness', 'b': 'Timid and fearful', 'c': 'Cautious and slow', 'd': 'Polite', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Audacious implies a bold disregard for normal constraints or danger.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: BELLIGERENT.', 'a': 'Hostile and aggressive', 'b': 'Peaceful and gentle', 'c': 'Friendly', 'd': 'Calm', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Belligerent means combative or eager to fight.', 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to the capitalized word: CACOPHONY.', 'a': 'A harsh, discordant mixture of sounds', 'b': 'Pleasant harmony', 'c': 'Complete silence', 'd': 'Melodious song', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Cacophony refers to a loud, grating, harsh dissonance.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: DEARTH.', 'a': 'A scarcity or lack of something', 'b': 'Abundant surplus', 'c': 'Wealth', 'd': 'Excess', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'A dearth is a state of shortage, inadequacy, or famine.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: DELETERIOUS.', 'a': 'Causing harm or damage', 'b': 'Beneficial and healthy', 'c': 'Neutral', 'd': 'Productive', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Deleterious describes something harmful, toxic, or injurious.', 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to the capitalized word: DIFFIDENT.', 'a': 'Modest or shy because of a lack of self-confidence', 'b': 'Assertive and bold', 'c': 'Arrogant', 'd': 'Sociable', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Diffident means hesitant in acting or speaking through lack of self-assurance.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: ENERVATE.', 'a': 'Cause someone to feel drained of energy; weaken', 'b': 'Invigorate and energize', 'c': 'Inspire', 'd': 'Heal', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'To enervate is to sap the physical, mental, or moral vitality of someone.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: EQUIVOCAL.', 'a': 'Open to more than one interpretation; ambiguous', 'b': 'Unambiguous and clear', 'c': 'Definite', 'd': 'Honest', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Equivocal language is deliberately vague or capable of differing interpretations.', 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to the capitalized word: FASTIDIOUS.', 'a': 'Very attentive to and concerned about accuracy and detail', 'b': 'Careless and sloppy', 'c': 'Lazy', 'd': 'Tolerant', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Fastidious means excessively particular, critical, or demanding.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: GARRULOUS.', 'a': 'Excessively talkative, especially on trivial matters', 'b': 'Taciturn and reticent', 'c': 'Quiet', 'd': 'Eloquent', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Garrulous means pointlessly or annoyingly loquacious.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: GREGARIOUS.', 'a': 'Fond of company; sociable', 'b': 'Antisocial and solitary', 'c': 'Hostile', 'd': 'Rude', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Gregarious individuals enjoy being around other people in social groups.', 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to the capitalized word: HACKNEYED.', 'a': 'Lacking significance through having been overused; cliché', 'b': 'Original and novel', 'c': 'Fresh', 'd': 'Inspiring', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Hackneyed phrases or ideas have grown stale through constant repetition.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: IMPETUOUS.', 'a': 'Acting or done quickly and without thought or care', 'b': 'Deliberate and cautious', 'c': 'Calculated', 'd': 'Patient', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Impetuous behavior is rash, impulsive, and unthinking.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: LACONIC.', 'a': 'Using very few words; concise', 'b': 'Verbose and rambling', 'c': 'Loud', 'd': 'Chatty', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Laconic speech is terse, pithy, and brief to the point of seeming blunt.', 'diff': 'EASY'}, {'q': 'Choose the word nearest in meaning to the capitalized word: MAGNANIMOUS.', 'a': 'Generous or forgiving, especially toward a rival', 'b': 'Vindictive and petty', 'c': 'Cruel', 'd': 'Selfish', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Magnanimous describes high-minded, noble generosity and grace in victory.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: NEFARIOUS.', 'a': 'Wicked, villainous, or criminal', 'b': 'Virtuous and honorable', 'c': 'Innocent', 'd': 'Kind', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Nefarious deeds are reprehensibly evil or iniquitous.', 'diff': 'MEDIUM'}, {'q': 'Choose the word nearest in meaning to the capitalized word: OBDURATE.', 'a': "Stubbornly refusing to change one's opinion or course", 'b': 'Pliable and flexible', 'c': 'Compliant', 'd': 'Gentle', 'ans': 'A', 'topic': 'Lexis & Vocabulary', 'exp': 'Obdurate means unmoved by persuasion, pity, or tender feelings.', 'diff': 'EASY'}, {'q': 'Neither the principal nor the teachers _______ present at the symposium.', 'a': 'was', 'b': 'were', 'c': 'is', 'd': 'are being', 'ans': 'B', 'topic': 'Concord', 'exp': 'In neither...nor, the verb agrees with the nearer subject (teachers -> were).', 'diff': 'MEDIUM'}, {'q': 'The committee _______ divided in their opinions regarding the zoning policy.', 'a': 'was', 'b': 'were', 'c': 'is', 'd': 'has been', 'ans': 'B', 'topic': 'Concord', 'exp': 'A collective noun takes a plural verb when individual members act independently or disagree.', 'diff': 'MEDIUM'}, {'q': 'One of the armed robbery suspects _______ escaped from lawful custody yesterday.', 'a': 'have', 'b': 'has', 'c': 'were', 'd': 'are', 'ans': 'B', 'topic': 'Concord', 'exp': "The grammatical subject is singular ('One'), hence it takes the singular verb 'has'.", 'diff': 'MEDIUM'}, {'q': 'The disciplinary panel, alongside the board members, _______ submitted the annual report.', 'a': 'have', 'b': 'has', 'c': 'are having', 'd': 'were', 'ans': 'B', 'topic': 'Concord', 'exp': "Parenthetical phrases like 'alongside' do not change the number of the subject ('panel' -> has).", 'diff': 'MEDIUM'}, {'q': 'Bread and butter _______ served as our regular breakfast in boarding school.', 'a': 'are', 'b': 'is', 'c': 'were', 'd': 'have been', 'ans': 'B', 'topic': 'Concord', 'exp': 'Compound subjects referring to a single collective dish take a singular verb.', 'diff': 'MEDIUM'}, {'q': 'Three-quarters of the arable farmland _______ been devastated by the flash flood.', 'a': 'has', 'b': 'have', 'c': 'are', 'd': 'were', 'ans': 'A', 'topic': 'Concord', 'exp': "Fractions take a singular verb when modifying singular or non-count nouns ('farmland' -> has).", 'diff': 'MEDIUM'}, {'q': 'More than one candidate _______ disqualified for possessing unauthorized electronic gadgets.', 'a': 'was', 'b': 'were', 'c': 'are', 'd': 'have been', 'ans': 'A', 'topic': 'Concord', 'exp': "'More than one' is grammatically followed by a singular noun and singular verb.", 'diff': 'MEDIUM'}, {'q': 'Many a brilliant graduate _______ roaming the streets in search of white-collar employment.', 'a': 'are', 'b': 'is', 'c': 'were', 'd': 'have been', 'ans': 'B', 'topic': 'Concord', 'exp': "'Many a' is followed by a singular countable noun and requires a singular verb.", 'diff': 'MEDIUM'}, {'q': 'Neither of the political parties _______ ready to accept the tribunal ruling.', 'a': 'are', 'b': 'is', 'c': 'were', 'd': 'have been', 'ans': 'B', 'topic': 'Concord', 'exp': "'Neither of' takes a singular verb in standard formal English.", 'diff': 'MEDIUM'}, {'q': 'Physics _______ considered an essential prerequisite for admission into engineering.', 'a': 'were', 'b': 'is', 'c': 'are', 'd': 'have been', 'ans': 'B', 'topic': 'Concord', 'exp': 'Academic disciplines ending in -s take singular verbs.', 'diff': 'MEDIUM'}, {'q': 'The jury _______ unanimously delivered its verdict before the presiding trial judge.', 'a': 'have', 'b': 'has', 'c': 'were', 'd': 'are', 'ans': 'B', 'topic': 'Concord', 'exp': "When a collective noun acts as a unified body, it takes a singular verb and pronoun ('its').", 'diff': 'MEDIUM'}, {'q': 'The rich also _______ their own peculiar family challenges and emotional burdens.', 'a': 'has', 'b': 'have', 'c': 'is having', 'd': 'was having', 'ans': 'B', 'topic': 'Concord', 'exp': "Adjectives functioning as plural collective nouns preceded by 'the' take plural verbs.", 'diff': 'MEDIUM'}, {'q': 'Ten million naira _______ demanded by the kidnappers as ransom money.', 'a': 'were', 'b': 'was', 'c': 'are', 'd': 'have been', 'ans': 'B', 'topic': 'Concord', 'exp': 'Sums of money and periods of time regarded as a lump sum take singular verbs.', 'diff': 'MEDIUM'}, {'q': 'Either the commercial driver or his conductors _______ responsible for the fare hike.', 'a': 'was', 'b': 'were', 'c': 'has been', 'd': 'is', 'ans': 'B', 'topic': 'Concord', 'exp': "In either...or constructions, the verb agrees with the closer subject ('conductors' -> were).", 'diff': 'MEDIUM'}, {'q': 'Not only the governor but also his commissioners _______ present at the groundbreaking ceremony.', 'a': 'was', 'b': 'were', 'c': 'is', 'd': 'has been', 'ans': 'B', 'topic': 'Concord', 'exp': "In 'not only...but also', the verb agrees with the adjacent subject ('commissioners' -> were).", 'diff': 'MEDIUM'}, {'q': 'The baggage _______ left unattended at the departure lounge for several hours.', 'a': 'were', 'b': 'was', 'c': 'are', 'd': 'have been', 'ans': 'B', 'topic': 'Grammar', 'exp': "'Baggage' is uncountable and takes a singular verb.", 'diff': 'MEDIUM'}, {'q': 'The police _______ arrested three notorious kidnap kingpins along the interstate highway.', 'a': 'has', 'b': 'have', 'c': 'was', 'd': 'is', 'ans': 'B', 'topic': 'Concord', 'exp': "'Police' is a plural collective noun and takes a plural verb.", 'diff': 'MEDIUM'}, {'q': 'The scissors _______ placed neatly inside the upper drawer of the technician desk.', 'a': 'was', 'b': 'were', 'c': 'is', 'd': 'has been', 'ans': 'B', 'topic': 'Concord', 'exp': "Two-part instruments take plural verbs unless preceded by 'a pair of'.", 'diff': 'MEDIUM'}, {'q': 'A pair of trousers _______ purchased from the boutique yesterday evening.', 'a': 'were', 'b': 'was', 'c': 'are', 'd': 'have been', 'ans': 'B', 'topic': 'Concord', 'exp': "'A pair of' makes the grammatical subject singular ('was').", 'diff': 'MEDIUM'}, {'q': 'Every teacher and student in the auditorium _______ given a commemorative badge.', 'a': 'were', 'b': 'was', 'c': 'are', 'd': 'have been', 'ans': 'B', 'topic': 'Concord', 'exp': "Nouns preceded by 'every' or 'each' take singular verbs even when coordinated with 'and'.", 'diff': 'MEDIUM'}, {'q': 'The belligerent posture of the warlord scuttled the international peace negotiations.', 'a': 'aggressive', 'b': 'conciliatory', 'c': 'diplomatic', 'd': 'indifferent', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Belligerent' means hostile, combative, or aggressive.", 'diff': 'MEDIUM'}, {'q': 'The government enacted stringent regulations to curb illicit financial flows across borders.', 'a': 'rigorous', 'b': 'lax', 'c': 'flexible', 'd': 'superficial', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Stringent' means strict, precise, and rigorous.", 'diff': 'MEDIUM'}, {'q': 'His ephemeral fame vanished shortly after the talent exhibition concluded.', 'a': 'transient', 'b': 'permanent', 'c': 'eternal', 'd': 'indispensable', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Ephemeral' means lasting for a very short duration; transient.", 'diff': 'MEDIUM'}, {'q': 'The witness gave an equivocal testimony that perplexed the defense counsels.', 'a': 'ambiguous', 'b': 'lucid', 'c': 'unambiguous', 'd': 'straightforward', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Equivocal' means open to multiple interpretations; ambiguous.", 'diff': 'MEDIUM'}, {'q': 'The managing director praised the tenacity of the marketing division during the economic recession.', 'a': 'persistence', 'b': 'hesitancy', 'c': 'recklessness', 'd': 'fragility', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Tenacity' means the quality of being persistent and resolute.", 'diff': 'MEDIUM'}, {'q': 'The philanthropic gesture of the oil magnate provided scholarships for hundreds of indigent scholars.', 'a': 'charitable', 'b': 'miserly', 'c': 'parsimonious', 'd': 'egotistical', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Philanthropic' means benevolent, generous, or charitable.", 'diff': 'MEDIUM'}, {'q': 'The prosecutor presented incontrovertible forensic evidence that sealed the conviction.', 'a': 'indisputable', 'b': 'questionable', 'c': 'circumstantial', 'd': 'dubious', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Incontrovertible' means undeniable or indisputable.", 'diff': 'MEDIUM'}, {'q': 'She had a meticulous approach to financial bookkeeping, ensuring zero discrepancies.', 'a': 'painstaking', 'b': 'careless', 'c': 'hasty', 'd': 'sloppy', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Meticulous' means showing great attention to detail; painstaking.", 'diff': 'MEDIUM'}, {'q': 'The pervasive stench from the open refuse dump contaminated the entire residential estate.', 'a': 'widespread', 'b': 'isolated', 'c': 'pleasant', 'd': 'mild', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Pervasive' means spreading widely throughout an area.", 'diff': 'MEDIUM'}, {'q': 'The candidate gave an audacious address demanding fundamental systemic constitutional reforms.', 'a': 'bold', 'b': 'timid', 'c': 'cowardly', 'd': 'hesitant', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Audacious' means showing a willingness to take bold risks.", 'diff': 'MEDIUM'}, {'q': 'The speaker was lauded for his eloquent presentation at the Pan-African youth summit.', 'a': 'fluent and persuasive', 'b': 'clumsy and hesitant', 'c': 'dull and monotonous', 'd': 'incoherent', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Eloquent' means fluent, expressive, and persuasive in speaking.", 'diff': 'MEDIUM'}, {'q': 'His ostentatious display of affluence attracted public reproach during the economic austerity.', 'a': 'flamboyant', 'b': 'modest', 'c': 'unassuming', 'd': 'frugal', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Ostentatious' means vulgar or pretentious display designed to impress.", 'diff': 'MEDIUM'}, {'q': 'The tribunal ruled that the company showed culpable negligence leading to the collapse.', 'a': 'blameworthy', 'b': 'praiseworthy', 'c': 'innocent', 'd': 'accidental', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Culpable' means deserving blame; guilty.", 'diff': 'MEDIUM'}, {'q': 'The politician made a candid confession about his past financial misdeeds.', 'a': 'frank and honest', 'b': 'deceitful', 'c': 'guarded', 'd': 'hypocritical', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Candid' means truthful, straightforward, and frank.", 'diff': 'MEDIUM'}, {'q': 'The ancient parchment was remarkably legible despite centuries of storage.', 'a': 'readable', 'b': 'obscure', 'c': 'illegible', 'd': 'faded', 'ans': 'A', 'topic': 'Synonyms', 'exp': "'Legible' means clear enough to be read.", 'diff': 'MEDIUM'}, {'q': 'The judge commended the defendant for his candid submission in the courtroom. (Opposite in meaning)', 'a': 'deceitful', 'b': 'frank', 'c': 'honest', 'd': 'forthright', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Candid' means frank; its antonym is deceitful or insincere.", 'diff': 'MEDIUM'}, {'q': 'The minister gave an impromptu address at the youth symposium. (Opposite in meaning)', 'a': 'rehearsed', 'b': 'unprepared', 'c': 'extemporaneous', 'd': 'spontaneous', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Impromptu' means done without preparation; its opposite is rehearsed.", 'diff': 'MEDIUM'}, {'q': 'The barren terrain yielded virtually no agricultural produce during the extended drought. (Opposite in meaning)', 'a': 'fertile', 'b': 'arid', 'c': 'desolate', 'd': 'sterile', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Barren' means unproductive; its antonym is fertile.", 'diff': 'MEDIUM'}, {'q': 'Her tacit agreement to the partnership terms surprised her business associates. (Opposite in meaning)', 'a': 'explicit', 'b': 'unspoken', 'c': 'implicit', 'd': 'silent', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Tacit' means implied; its antonym is explicit.", 'diff': 'MEDIUM'}, {'q': 'The general was notorious for his ruthless suppression of dissenting military factions. (Opposite in meaning)', 'a': 'merciful', 'b': 'cruel', 'c': 'tyrannical', 'd': 'callous', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Ruthless' means without pity; its antonym is merciful.", 'diff': 'MEDIUM'}, {'q': 'The corporation recorded colossal financial losses in the final quarter. (Opposite in meaning)', 'a': 'negligible', 'b': 'huge', 'c': 'gigantic', 'd': 'enormous', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Colossal' means extremely large; its antonym is negligible.", 'diff': 'MEDIUM'}, {'q': 'The island lived in pristine ecological conditions prior to commercial oil exploration. (Opposite in meaning)', 'a': 'polluted', 'b': 'pure', 'c': 'unspoilt', 'd': 'immaculate', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Pristine' means in original pure condition; its antonym is polluted.", 'diff': 'MEDIUM'}, {'q': 'The commandant issued a mandatory directive for all active personnel to muster. (Opposite in meaning)', 'a': 'optional', 'b': 'compulsory', 'c': 'obligatory', 'd': 'imperative', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Mandatory' means compulsory; its antonym is optional.", 'diff': 'MEDIUM'}, {'q': 'His arrogant disposition alienated several of his longstanding associates. (Opposite in meaning)', 'a': 'humble', 'b': 'haughty', 'c': 'pompous', 'd': 'supercilious', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Arrogant' means conceited; its opposite is humble.", 'diff': 'MEDIUM'}, {'q': 'The supreme court declared the disputed decree null and void. (Opposite in meaning)', 'a': 'valid', 'b': 'invalid', 'c': 'ineffectual', 'd': 'revoked', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Null and void' means invalid; its opposite is valid.", 'diff': 'MEDIUM'}, {'q': 'The diplomat handled the volatile territorial dispute with extraordinary equanimity. (Opposite in meaning)', 'a': 'agitation', 'b': 'calmness', 'c': 'serenity', 'd': 'poise', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Equanimity' means mental calmness; its antonym is agitation.", 'diff': 'MEDIUM'}, {'q': 'The theologian held orthodox views on liturgical worship and doctrinal canons. (Opposite in meaning)', 'a': 'heterodox', 'b': 'traditional', 'c': 'conventional', 'd': 'conservative', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Orthodox' means conforming to established doctrine; its antonym is heterodox.", 'diff': 'MEDIUM'}, {'q': 'The apprentice was commended for being industrious throughout the technical attachment. (Opposite in meaning)', 'a': 'indolent', 'b': 'diligent', 'c': 'hardworking', 'd': 'assiduous', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Industrious' means hardworking; its opposite is indolent or lazy.", 'diff': 'MEDIUM'}, {'q': 'The demagogue delivered an inflammatory address that incited communal skirmishes. (Opposite in meaning)', 'a': 'soothing', 'b': 'provocative', 'c': 'incendiary', 'd': 'hostile', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Inflammatory' means arousing violent passions; its antonym is soothing.", 'diff': 'MEDIUM'}, {'q': 'The treasurer maintained a parsimonious budget during the financial crisis. (Opposite in meaning)', 'a': 'extravagant', 'b': 'frugal', 'c': 'miserly', 'd': 'thrifty', 'ans': 'A', 'topic': 'Antonyms', 'exp': "'Parsimonious' means excessively frugal; its antonym is extravagant.", 'diff': 'MEDIUM'}, {'q': 'The union representatives decided to call _______ the general strike after reaching an agreement.', 'a': 'off', 'b': 'out', 'c': 'up', 'd': 'down', 'ans': 'A', 'topic': 'Phrasal Verbs', 'exp': "'To call off' means to cancel an event or strike action.", 'diff': 'MEDIUM'}, {'q': 'The student refused to abide _______ the hostel disciplinary regulations.', 'a': 'by', 'b': 'with', 'c': 'to', 'd': 'in', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The verb 'abide' in the sense of complying with rules collocates with 'by'.", 'diff': 'MEDIUM'}, {'q': 'She found it stressful to cope _______ both rigorous graduate coursework and full-time employment.', 'a': 'with', 'b': 'up with', 'c': 'about', 'd': 'through', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The correct English idiom is 'cope with', not 'cope up with'.", 'diff': 'MEDIUM'}, {'q': 'The forensic auditor stumbled _______ confidential ledger entries detailing the fraud.', 'a': 'upon', 'b': 'into', 'c': 'with', 'd': 'at', 'ans': 'A', 'topic': 'Prepositions', 'exp': "To find unexpectedly is to 'stumble on/upon'.", 'diff': 'MEDIUM'}, {'q': 'The senate committee promised to look _______ the complaints lodged by the student union.', 'a': 'into', 'b': 'over', 'c': 'out', 'd': 'up', 'ans': 'A', 'topic': 'Phrasal Verbs', 'exp': "'To look into' means to investigate thoroughly.", 'diff': 'MEDIUM'}, {'q': 'The defendant was completely exonerated _______ any complicity in the treasonous conspiracy.', 'a': 'from', 'b': 'of', 'c': 'with', 'd': 'in', 'ans': 'A', 'topic': 'Prepositions', 'exp': "One is exonerated 'from' or 'of' criminal charges.", 'diff': 'MEDIUM'}, {'q': 'His sudden resignation from the cabinet came as a bolt from the _______ to political analysts.', 'a': 'blue', 'b': 'sky', 'c': 'clouds', 'd': 'storm', 'ans': 'A', 'topic': 'Idioms', 'exp': "'A bolt from the blue' means a sudden, unexpected event.", 'diff': 'MEDIUM'}, {'q': 'The corrupt official used his public position to feather his own nest. This means he:', 'a': 'enriched himself dishonestly', 'b': 'beautified his residence', 'c': 'raised domestic birds', 'd': 'resigned voluntarily', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To feather one's nest' means to make oneself wealthy dishonestly through public office.", 'diff': 'MEDIUM'}, {'q': 'The prime minister decided to take the bull by the horns by dissolving the rebellious parliament. This means he:', 'a': 'confronted the difficult crisis decisively', 'b': 'acted in fear', 'c': 'consulted an astrologer', 'd': 'evaded the issue', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To take the bull by the horns' means to deal with a crisis directly and courageously.", 'diff': 'MEDIUM'}, {'q': 'When interrogated under oath, the accomplice decided to spill the beans. This means he:', 'a': 'divulged the secret conspiracy', 'b': 'scattered farm grains', 'c': 'refused to testify', 'd': 'escaped through the window', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To spill the beans' means to reveal confidential information or secrets.", 'diff': 'MEDIUM'}, {'q': 'He still has a chip on his shoulder regarding his dismissal from the academy. This means he:', 'a': 'harbors an enduring grievance and resentment', 'b': 'carries heavy timber', 'c': 'suffers from back injury', 'd': 'feels remorseful', 'ans': 'A', 'topic': 'Idioms', 'exp': "Having a 'chip on one's shoulder' means harboring a grudge or bitter grievance.", 'diff': 'MEDIUM'}, {'q': 'After receiving the national literary award, she was cautioned not to rest on her _______.', 'a': 'laurels', 'b': 'bed', 'c': 'chair', 'd': 'trophies', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To rest on one's laurels' means to be satisfied with past achievements and make no further effort.", 'diff': 'MEDIUM'}, {'q': 'The procurement tender was rejected because it failed to conform _______ statutory guidelines.', 'a': 'to', 'b': 'with', 'c': 'for', 'd': 'about', 'ans': 'A', 'topic': 'Prepositions', 'exp': "'Conform to' or 'conform with' indicates adherence; 'to' is standard here.", 'diff': 'MEDIUM'}, {'q': 'The accountant was convicted of conniving _______ external syndicates to forge bank drafts.', 'a': 'with', 'b': 'at', 'c': 'in', 'd': 'to', 'ans': 'A', 'topic': 'Prepositions', 'exp': "One connives 'with' a co-conspirator to commit fraud.", 'diff': 'MEDIUM'}, {'q': 'The reckless driver was formally charged _______ vehicular manslaughter in the magistrate court.', 'a': 'with', 'b': 'for', 'c': 'of', 'd': 'in', 'ans': 'A', 'topic': 'Prepositions', 'exp': "In legal jurisprudence, an accused person is 'charged with' an offense.", 'diff': 'MEDIUM'}, {'q': "Which of the following words contains the identical vowel sound to that in 'key'?", 'a': 'quay', 'b': 'leopard', 'c': 'bread', 'd': 'said', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Quay' is pronounced /ki:/, which shares the long vowel /i:/ found in 'key'.", 'diff': 'MEDIUM'}, {'q': "Identify the word sharing the same central long vowel sound as 'b_ir_d':", 'a': 'fern', 'b': 'beard', 'c': 'hair', 'd': 'fear', 'ans': 'A', 'topic': 'Oral English', 'exp': "The long central vowel in 'bird' /bɜ:d/ is identical to that in 'fern' /fɜ:n/.", 'diff': 'MEDIUM'}, {'q': 'Which of the following words contains the diphthong /aɪ/?', 'a': 'eye', 'b': 'oil', 'c': 'toy', 'd': 'day', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Eye' is pronounced /aɪ/, matching 'my', 'pie', and 'high'.", 'diff': 'MEDIUM'}, {'q': 'Identify the word that contains the voiceless dental fricative sound /θ/:', 'a': 'thin', 'b': 'this', 'c': 'then', 'd': 'mother', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Thin' begins with the voiceless dental fricative /θ/, whereas 'this' and 'then' have voiced /ð/.", 'diff': 'MEDIUM'}, {'q': 'Which of the following words contains the voiced dental fricative sound /ð/?', 'a': 'feather', 'b': 'thought', 'c': 'theft', 'd': 'threat', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Feather' contains the voiced dental fricative /ð/, whereas the others have voiceless /θ/.", 'diff': 'MEDIUM'}, {'q': "In which of the following words is the initial consonant letter 'p' silent?", 'a': 'psalm', 'b': 'party', 'c': 'pencil', 'd': 'copper', 'ans': 'A', 'topic': 'Oral English', 'exp': "The letter 'p' is silent in 'psalm' /sɑ:m/, as well as in 'psychology'.", 'diff': 'MEDIUM'}, {'q': "In which of the following words is the letter 'b' silent in pronunciation?", 'a': 'doubt', 'b': 'table', 'c': 'timber', 'd': 'bubble', 'ans': 'A', 'topic': 'Oral English', 'exp': "The letter 'b' is silent before 't' in 'doubt' and after 'm' in 'tomb'.", 'diff': 'MEDIUM'}, {'q': 'Identify the word that contains the short vowel sound /æ/:', 'a': 'cat', 'b': 'father', 'c': 'caught', 'd': 'cart', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Cat' has the short front open vowel /æ/, whereas 'father' has /ɑ:/.", 'diff': 'MEDIUM'}, {'q': "Which of the following words rhymes with 'cough'?", 'a': 'off', 'b': 'bough', 'c': 'rough', 'd': 'through', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Cough' is pronounced /kɒf/ and rhymes perfectly with 'off' /ɒf/.", 'diff': 'MEDIUM'}, {'q': "Identify the word that contains the sound /tʃ/ as in 'chair':", 'a': 'nature', 'b': 'machine', 'c': 'chemist', 'd': 'character', 'ans': 'A', 'topic': 'Oral English', 'exp': "The 't' in 'nature' is pronounced /tʃ/ (/ˈneɪtʃər/).", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in the noun 'CON-DUCT' (behavior)?", 'a': 'first syllable', 'b': 'second syllable', 'c': 'both syllables equally', 'd': 'neither syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': 'Two-syllable words functioning as nouns generally take stress on the first syllable.', 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in the verb 'con-DUCT' (to direct or lead)?", 'a': 'second syllable', 'b': 'first syllable', 'c': 'third syllable', 'd': 'both syllables', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': 'Two-syllable words functioning as verbs generally take stress on the second syllable.', 'diff': 'MEDIUM'}, {'q': "In the word 'PHOTOGRAPHY', on which syllable does the primary stress fall?", 'a': 'second syllable (pho-TOG-ra-phy)', 'b': 'first syllable', 'c': 'third syllable', 'd': 'fourth syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-graphy' take primary stress on the antepenultimate syllable.", 'diff': 'MEDIUM'}, {'q': "In the word 'DEMOCRATIC', which syllable receives the primary stress?", 'a': 'third syllable (de-mo-CRAT-ic)', 'b': 'first syllable', 'c': 'second syllable', 'd': 'fourth syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-ic' take primary stress on the syllable immediately preceding the suffix.", 'diff': 'MEDIUM'}, {'q': "In the word 'EDUCATION', which syllable receives the primary stress?", 'a': 'third syllable (ed-u-CA-tion)', 'b': 'first syllable', 'c': 'second syllable', 'd': 'fourth syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-tion' receive primary stress on the penultimate syllable.", 'diff': 'MEDIUM'}, {'q': 'If he _______ worked harder during the term, he would have passed the promotional examination.', 'a': 'had', 'b': 'has', 'c': 'have', 'd': 'would have', 'ans': 'A', 'topic': 'Conditionals', 'exp': "Third conditional clauses express past counterfactuals using 'had + past participle'.", 'diff': 'MEDIUM'}, {'q': 'I would rather you _______ the assignment before Friday evening.', 'a': 'completed', 'b': 'complete', 'c': 'had completed', 'd': 'completes', 'ans': 'A', 'topic': 'Subjunctive', 'exp': "'Would rather' followed by a subject takes a past subjunctive verb form to express present or future preference.", 'diff': 'MEDIUM'}, {'q': 'It is high time we _______ for the examination hall.', 'a': 'left', 'b': 'leave', 'c': 'are leaving', 'd': 'have left', 'ans': 'A', 'topic': 'Subjunctive', 'exp': "The structure 'It is high time' takes the past subjunctive form of the verb.", 'diff': 'MEDIUM'}, {'q': 'Scarcely had the referee blown the whistle _______ the jubilant supporters invaded the pitch.', 'a': 'when', 'b': 'than', 'c': 'then', 'd': 'before', 'ans': 'A', 'topic': 'Correlative Conjunctions', 'exp': "'Scarcely' and 'hardly' correlate with 'when', whereas 'no sooner' correlates with 'than'.", 'diff': 'MEDIUM'}, {'q': 'No sooner had the principal entered the classroom _______ the unruly students fell silent.', 'a': 'than', 'b': 'when', 'c': 'then', 'd': 'before', 'ans': 'A', 'topic': 'Correlative Conjunctions', 'exp': "'No sooner' is correlatively followed by 'than'.", 'diff': 'MEDIUM'}, {'q': 'The doctor advised the diabetic patient to abstain _______ sugary beverages and refined flour.', 'a': 'from', 'b': 'with', 'c': 'to', 'd': 'against', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The verb 'abstain' correctly collocates with the preposition 'from'.", 'diff': 'MEDIUM'}, {'q': 'The young athlete was disqualified because he was found deficient _______ basic cardiovascular endurance.', 'a': 'in', 'b': 'of', 'c': 'with', 'd': 'at', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The adjective 'deficient' takes the preposition 'in'.", 'diff': 'MEDIUM'}, {'q': 'The new tax reform policy is detrimental _______ small and medium scale business enterprises.', 'a': 'to', 'b': 'for', 'c': 'with', 'd': 'against', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The adjective 'detrimental' collocates with the preposition 'to'.", 'diff': 'MEDIUM'}, {'q': 'The reckless driver was impervious _______ repeated warnings from traffic wardens.', 'a': 'to', 'b': 'with', 'c': 'for', 'd': 'against', 'ans': 'A', 'topic': 'Prepositions', 'exp': "'Impervious' takes the preposition 'to'.", 'diff': 'MEDIUM'}, {'q': 'He was completely oblivious _______ the impending danger surrounding the campsite.', 'a': 'to', 'b': 'with', 'c': 'at', 'd': 'against', 'ans': 'A', 'topic': 'Prepositions', 'exp': "'Oblivious' takes the preposition 'to' or 'of'.", 'diff': 'MEDIUM'}, {'q': 'The committee was unanimous _______ its decision to expel the cult members.', 'a': 'in', 'b': 'with', 'c': 'for', 'd': 'at', 'ans': 'A', 'topic': 'Prepositions', 'exp': "'Unanimous' takes the preposition 'in' when referring to an action or decision.", 'diff': 'MEDIUM'}, {'q': 'The defense lawyer argued that the confession was obtained _______ duress.', 'a': 'under', 'b': 'in', 'c': 'with', 'd': 'by', 'ans': 'A', 'topic': 'Prepositions', 'exp': "In legal parlance, an act performed under coercion is done 'under duress'.", 'diff': 'MEDIUM'}, {'q': 'The newly inaugurated bridge was named _______ the renowned nationalist hero.', 'a': 'after', 'b': 'for', 'c': 'by', 'd': 'with', 'ans': 'A', 'topic': 'Prepositions', 'exp': "To name someone or something in honor of another person is to name it 'after' them.", 'diff': 'MEDIUM'}, {'q': 'The manager commended the secretary for her unwavering fidelity _______ corporate ethics.', 'a': 'to', 'b': 'with', 'c': 'for', 'd': 'in', 'ans': 'A', 'topic': 'Prepositions', 'exp': "'Fidelity' collocates with 'to'.", 'diff': 'MEDIUM'}, {'q': 'She was acquitted and discharged _______ all charges of treasonable felony.', 'a': 'of', 'b': 'from', 'c': 'with', 'd': 'in', 'ans': 'A', 'topic': 'Prepositions', 'exp': "In legal context, one is acquitted 'of' a charge.", 'diff': 'MEDIUM'}, {'q': "The philanthropist is renowned for his altruistic deeds toward orphanages. 'Altruistic' means:", 'a': 'selfless and benevolent', 'b': 'selfish and greedy', 'c': 'cautious and timid', 'd': 'cynical and bitter', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Altruistic means showing selfless concern for the well-being of others.', 'diff': 'MEDIUM'}, {'q': "Her capricious mood swings alienated her closest colleagues. 'Capricious' means:", 'a': 'unpredictable and erratic', 'b': 'steadfast and dependable', 'c': 'joyful and exuberant', 'd': 'calm and composed', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Capricious means given to sudden and unaccountable changes of mood or behavior.', 'diff': 'MEDIUM'}, {'q': "The surgeon was acclaimed for his dexterous handling of micro-instruments. 'Dexterous' means:", 'a': 'skillful with hands', 'b': 'clumsy and uncoordinated', 'c': 'hesitant and fearful', 'd': 'rough and careless', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Dexterous means showing or having skill, especially with the hands.', 'diff': 'MEDIUM'}, {'q': "The ancient inscription remained an enigmatic puzzle to modern archeologists. 'Enigmatic' means:", 'a': 'mysterious and difficult to interpret', 'b': 'plain and obvious', 'c': 'transparent and lucid', 'd': 'irrelevant and trivial', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Enigmatic means difficult to interpret or understand; mysterious.', 'diff': 'MEDIUM'}, {'q': "He is a fastidious scholar who rejects any paper containing typographical errors. 'Fastidious' means:", 'a': 'very attentive to accuracy and detail', 'b': 'careless and indifferent', 'c': 'generous and accommodating', 'd': 'hasty and superficial', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Fastidious means very attentive to and concerned about accuracy and detail.', 'diff': 'MEDIUM'}, {'q': "Her gregarious nature made her the life of every social gathering. 'Gregarious' means:", 'a': 'sociable and fond of company', 'b': 'solitary and reclusive', 'c': 'timid and reserved', 'd': 'hostile and quarrelsome', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Gregarious means fond of company; sociable.', 'diff': 'MEDIUM'}, {'q': "The haughty aristocrat refused to acknowledge the peasants greetings. 'Haughty' means:", 'a': 'arrogantly superior and disdainful', 'b': 'humble and meek', 'c': 'courteous and polite', 'd': 'sympathetic and kind', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Haughty means arrogantly superior and disdainful.', 'diff': 'MEDIUM'}, {'q': "The insect bite was relatively innocuous and caused no allergic reaction. 'Innocuous' means:", 'a': 'not harmful or offensive', 'b': 'lethal and venomous', 'c': 'painful and infectious', 'd': 'grotesque and hideous', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Innocuous means not harmful or offensive.', 'diff': 'MEDIUM'}, {'q': "The museum curator chose to juxtapose classical sculptures with contemporary abstract paintings. 'Juxtapose' means:", 'a': 'place close together for contrasting effect', 'b': 'separate into distant halls', 'c': 'conceal from public view', 'd': 'destroy or dismantle', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Juxtapose means to place different things side by side to highlight a contrast.', 'diff': 'MEDIUM'}, {'q': "Pure gold is an exceptionally malleable metal used in decorative gilding. 'Malleable' means:", 'a': 'easily hammered or pressed into shape', 'b': 'brittle and fragile', 'c': 'rigid and unbending', 'd': 'dense and non-conductive', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Malleable means able to be hammered or pressed permanently out of shape without breaking.', 'diff': 'MEDIUM'}, {'q': "The factory emitted noxious chemical effluents into the urban river. 'Noxious' means:", 'a': 'harmful, poisonous, or very unpleasant', 'b': 'beneficial and enriching', 'c': 'odorless and pure', 'd': 'sparkling and clear', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Noxious means harmful, poisonous, or very unpleasant.', 'diff': 'MEDIUM'}, {'q': "The dark ominous storm clouds gathered over the coastal horizon. 'Ominous' means:", 'a': 'giving the impression that something bad is about to happen', 'b': 'promising and bright', 'c': 'cheerful and welcoming', 'd': 'peaceful and serene', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Ominous means giving the worrying impression that something bad is about to happen; threatening.', 'diff': 'MEDIUM'}, {'q': "Chinua Achebe was a prolific writer whose essays and novels shaped African literature. 'Prolific' means:", 'a': 'producing much fruit or foliage or many works', 'b': 'unproductive and sterile', 'c': 'sluggish and lazy', 'd': 'obscure and forgotten', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Prolific means producing a large amount of creative work.', 'diff': 'MEDIUM'}, {'q': "The editor removed redundant paragraphs to improve the essays concise flow. 'Redundant' means:", 'a': 'not or no longer needed or useful; superfluous', 'b': 'essential and indispensable', 'c': 'creative and imaginative', 'd': 'original and fresh', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Redundant means unnecessary; exceeding what is required.', 'diff': 'MEDIUM'}, {'q': "The resilient economy rebounded swiftly following the macroeconomic interventions. 'Resilient' means:", 'a': 'able to withstand or recover quickly from difficult conditions', 'b': 'fragile and easily shattered', 'c': 'stagnant and declining', 'd': 'unresponsive and rigid', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Resilient means able to recover rapidly from adversity.', 'diff': 'MEDIUM'}, {'q': "The stoic warrior bore his severe battlefield wounds without uttering a single complaint. 'Stoic' means:", 'a': 'enduring pain without displaying feelings or complaining', 'b': 'hysterical and weeping', 'c': 'cowardly and trembling', 'd': 'aggressive and vengeful', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Stoic means a person who can endure pain or hardship without showing their feelings or complaining.', 'diff': 'MEDIUM'}, {'q': "Mobile smartphones have become ubiquitous in both urban and rural communities. 'Ubiquitous' means:", 'a': 'present, appearing, or found everywhere', 'b': 'rare and scarce', 'c': 'extinct and obsolete', 'd': 'expensive and exclusive', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Ubiquitous means present, appearing, or found everywhere.', 'diff': 'MEDIUM'}, {'q': "She is a versatile musician proficient in violin, piano, and traditional drums. 'Versatile' means:", 'a': 'able to adapt or be adapted to many different functions or activities', 'b': 'inflexible and limited', 'c': 'untrained and amateur', 'd': 'clumsy and hesitant', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Versatile means capable of doing many different things well.', 'diff': 'MEDIUM'}, {'q': "The religious zealot was unwilling to entertain any dissenting viewpoints. 'Zealot' means:", 'a': 'a person who is fanatical and uncompromising in pursuit of their ideals', 'b': 'a moderate and balanced thinker', 'c': 'an agnostic skeptic', 'd': 'a peaceful mediator', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Zealot means a person who is fanatical and uncompromising in pursuit of their religious or political ideals.', 'diff': 'MEDIUM'}, {'q': "The electorate felt ambivalent about both candidates running for mayor. 'Ambivalent' means:", 'a': 'having mixed feelings or contradictory ideas about something', 'b': 'absolutely certain and resolute', 'c': 'enthusiastic and passionate', 'd': 'completely indifferent', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Ambivalent means having mixed or conflicting emotions about something.', 'diff': 'MEDIUM'}, {'q': "The judge commended the lawyer for his lucid presentation of the complex constitutional case. 'Lucid' means:", 'a': 'clear and easy to understand', 'b': 'confused and muddled', 'c': 'boring and lengthy', 'd': 'aggressive and loud', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Lucid means expressed clearly; easy to understand.', 'diff': 'MEDIUM'}, {'q': "His parsimonious lifestyle surprised those who knew his immense wealth. 'Parsimonious' means:", 'a': 'extremely frugal or miserly', 'b': 'generous and lavish', 'c': 'reckless and wasteful', 'd': 'charitable and kind', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Parsimonious means unwilling to spend money; excessively frugal.', 'diff': 'MEDIUM'}, {'q': "The ephemeral blossom of the night-blooming cereus withers before dawn. 'Ephemeral' means:", 'a': 'short-lived and transient', 'b': 'perennial and lasting', 'c': 'evergreen and sturdy', 'd': 'artificial and fake', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Ephemeral means lasting for a very short time.', 'diff': 'MEDIUM'}, {'q': "The prime minister's speech was laden with platitudes rather than actionable policy proposals. 'Platitudes' means:", 'a': 'trite or banal remarks uttered as if original', 'b': 'profound philosophical insights', 'c': 'sharp witty jokes', 'd': 'scientific equations', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Platitude means a flat, dull, or trite remark uttered as if it were fresh or profound.', 'diff': 'MEDIUM'}, {'q': "She approached her new research endeavor with infectious zeal. 'Zeal' means:", 'a': 'great energy or enthusiasm in pursuit of a cause', 'b': 'reluctance and hesitation', 'c': 'weariness and apathy', 'd': 'fear and anxiety', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Zeal means great passion, energy, or enthusiasm for a cause.', 'diff': 'MEDIUM'}, {'q': "The defendant claimed he was acting under duress when he signed the confession. 'Duress' means:", 'a': 'threats, violence, or coercion brought to bear on someone', 'b': 'free and voluntary consent', 'c': 'legal representation by counsel', 'd': 'physical intoxication', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Duress means threats, violence, constraints, or other action used to force someone to do something against their will.', 'diff': 'MEDIUM'}, {'q': "His caustic remarks during the staff meeting deeply offended his colleagues. 'Caustic' means:", 'a': 'sarcastic in a scathing and bitter way', 'b': 'soothing and complimentary', 'c': 'polite and formal', 'd': 'quiet and whispered', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Caustic means sarcastic, stinging, or biting in tone.', 'diff': 'MEDIUM'}, {'q': "The company was found guilty of deceptive packaging designed to mislead consumers. 'Deceptive' means:", 'a': 'giving an appearance or impression different from the true one; misleading', 'b': 'transparent and honest', 'c': 'durable and strong', 'd': 'innovative and modern', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Deceptive means misleading or intended to deceive.', 'diff': 'MEDIUM'}, {'q': "The diplomat possessed remarkable tact, resolving disputes without offending either party. 'Tact' means:", 'a': 'skill and sensitivity in dealing with others or with difficult issues', 'b': 'blunt rudeness', 'c': 'cowardice and retreat', 'd': 'dishonesty and fraud', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Tact means skill and sensitivity in dealing with difficult issues or interpersonal relationships.', 'diff': 'MEDIUM'}, {'q': "The newly ordained priest was revered for his piety and devotion to community welfare. 'Piety' means:", 'a': 'the quality of being religious or reverent', 'b': 'pride and arrogance', 'c': 'greed and avarice', 'd': 'cynicism and doubt', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Piety means the quality of being reverent, devout, and religious.', 'diff': 'MEDIUM'}, {'q': "The king issued an amnesty pardoning all political dissidents who surrendered arms. 'Amnesty' means:", 'a': 'an official pardon for people convicted of political offenses', 'b': 'a death warrant', 'c': 'a declaration of war', 'd': 'a tax levy', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Amnesty is an official government pardon for political offenses.', 'diff': 'MEDIUM'}, {'q': "The torrential rainfall caused unprecedented flooding across low-lying coastal plains. 'Unprecedented' means:", 'a': 'never done or known before', 'b': 'customary and expected', 'c': 'insignificant and trivial', 'd': 'annual and predictable', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Unprecedented means never having happened or existed in the past.', 'diff': 'MEDIUM'}, {'q': "The scientist put forward an ingenious hypothesis explaining solar flares. 'Ingenious' means:", 'a': 'clever, original, and inventive', 'b': 'naive and gullible', 'c': 'clumsy and unworkable', 'd': 'outdated and disproved', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Ingenious means marked by inventive skill and cleverness.', 'diff': 'MEDIUM'}, {'q': "The government established a buffer stock to stabilize food prices during crop failure. 'Buffer' means:", 'a': 'something that lessens the impact of harmful changes', 'b': 'an offensive weapon', 'c': 'a financial debt', 'd': 'a legal decree', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'A buffer is a safeguard or cushion designed to absorb shocks and stabilize conditions.', 'diff': 'MEDIUM'}, {'q': "The artist was celebrated for the aesthetic harmony of her oil canvases. 'Aesthetic' means:", 'a': 'concerned with beauty or the appreciation of beauty', 'b': 'functional and utilitarian', 'c': 'cheap and shoddy', 'd': 'commercial and industrial', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Aesthetic relates to beauty and artistic taste.', 'diff': 'MEDIUM'}, {'q': "The juvenile court magistrate took a lenient view of the first-time petty offender. 'Lenient' means:", 'a': 'more merciful or tolerant than expected', 'b': 'harsh and punitive', 'c': 'vengeful and cruel', 'd': 'indifferent and bored', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Lenient means characterized by mercy or tolerance rather than severity.', 'diff': 'MEDIUM'}, {'q': "The community elder was revered for his sagacity in mediating communal boundary disputes. 'Sagacity' means:", 'a': 'acuteness of mental discernment and sound judgment; wisdom', 'b': 'foolishness and rashness', 'c': 'deceit and cunning', 'd': 'wealth and affluence', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Sagacity denotes profound wisdom, insight, and good judgment.', 'diff': 'MEDIUM'}, {'q': "The politician was accused of nepotism after appointing three unqualified nephews to public boards. 'Nepotism' means:", 'a': 'favoritism shown to relatives, especially by giving them jobs', 'b': 'merit-based employment', 'c': 'racial discrimination', 'd': 'religious intolerance', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Nepotism is the unfair practice of granting favors or positions to family members.', 'diff': 'MEDIUM'}, {'q': "The monastery offered a tranquil sanctuary far from the clamor of metropolitan life. 'Tranquil' means:", 'a': 'calm, peaceful, and quiet', 'b': 'chaotic and noisy', 'c': 'hazardous and unsafe', 'd': 'congested and busy', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Tranquil means free from disturbance; calm and serene.', 'diff': 'MEDIUM'}, {'q': "The defendant demonstrated profound remorse for his reckless driving that caused the accident. 'Remorse' means:", 'a': 'deep regret or guilt for a wrong committed', 'b': 'triumph and pride', 'c': 'indifference and callousness', 'd': 'pleasure and joy', 'ans': 'A', 'topic': 'Vocabulary', 'exp': 'Remorse is a gnawing sense of distress arising from a feeling of guilt for past misdeeds.', 'diff': 'MEDIUM'}, {'q': "In the sentence 'The boy who won the national spelling bee is my cousin', the clause 'who won the national spelling bee' is a:", 'a': "defining relative clause qualifying 'The boy'", 'b': 'non-defining relative clause', 'c': 'adverbial clause of reason', 'd': 'noun clause in apposition', 'ans': 'A', 'topic': 'Clause Analysis', 'exp': "The relative clause restricts and defines the specific noun 'boy'.", 'diff': 'MEDIUM'}, {'q': 'Identify the sentence containing an intransitive verb:', 'a': 'The golden eagle soared majestically above the jagged mountain cliffs.', 'b': 'The farmer harvested twenty bags of yellow maize.', 'c': 'The carpenter constructed a durable mahogany dining table.', 'd': 'The teacher praised the attentive pupils in the classroom.', 'ans': 'A', 'topic': 'Grammar', 'exp': "'Soared' is an intransitive verb because it does not take a direct object.", 'diff': 'MEDIUM'}, {'q': 'Which of the following sentences illustrates the correct use of a gerund as the subject?', 'a': 'Swimming regularly enhances cardiovascular endurance and lung capacity.', 'b': 'To swim across the wide river was his ambition.', 'c': 'The boy is swimming in the Olympic pool.', 'd': 'Having swam across the river, he rested on the bank.', 'ans': 'A', 'topic': 'Grammar', 'exp': "'Swimming' in this sentence functions as a verbal noun (gerund) serving as the grammatical subject.", 'diff': 'MEDIUM'}, {'q': "In the sentence 'She gave her younger brother an expensive wrist watch', the noun phrase 'her younger brother' functions as the:", 'a': 'indirect object', 'b': 'direct object', 'c': 'subject complement', 'd': 'object complement', 'ans': 'A', 'topic': 'Grammar', 'exp': "'Her younger brother' is the indirect recipient of the direct object ('an expensive wrist watch').", 'diff': 'MEDIUM'}, {'q': 'Identify the sentence with correct punctuation and comma placement:', 'a': 'Although the torrential rain poured incessantly, the football match proceeded as scheduled.', 'b': 'Although the torrential rain poured incessantly the football match proceeded as scheduled.', 'c': 'Although the torrential rain poured, incessantly the football match proceeded, as scheduled.', 'd': 'Although, the torrential rain poured incessantly the football match proceeded as scheduled.', 'ans': 'A', 'topic': 'Punctuation', 'exp': 'An introductory adverbial clause must be separated from the independent main clause by a comma.', 'diff': 'MEDIUM'}, {'q': "Which of the following words contains a silent 't' in its standard British pronunciation?", 'a': 'listen', 'b': 'little', 'c': 'matter', 'd': 'water', 'ans': 'A', 'topic': 'Oral English', 'exp': "The letter 't' is silent in 'listen' (/ˈlɪs.ən/), as well as in 'castle', 'whistle', and 'fasten'.", 'diff': 'MEDIUM'}, {'q': "Which word contains a silent 'k' in its pronunciation?", 'a': 'knight', 'b': 'king', 'c': 'kite', 'd': 'kitchen', 'ans': 'A', 'topic': 'Oral English', 'exp': "The letter 'k' before 'n' at the beginning of a word is silent ('knight' /naɪt/).", 'diff': 'MEDIUM'}, {'q': "Identify the word that contains a silent 'w' in its pronunciation:", 'a': 'sword', 'b': 'sweet', 'c': 'swift', 'd': 'swear', 'ans': 'A', 'topic': 'Oral English', 'exp': "The 'w' is silent in 'sword' (/sɔ:d/), as well as in 'two' and 'answer'.", 'diff': 'MEDIUM'}, {'q': "Which of the following words contains a silent 'l' in its standard pronunciation?", 'a': 'salmon', 'b': 'silver', 'c': 'soldier', 'd': 'candle', 'ans': 'A', 'topic': 'Oral English', 'exp': "The letter 'l' is silent in 'salmon' (/ˈsæm.ən/), 'calm', 'palm', and 'half'.", 'diff': 'MEDIUM'}, {'q': "Which word contains the diphthong /eə/ as in 'hair'?", 'a': 'care', 'b': 'fear', 'c': 'dear', 'd': 'near', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Care' is pronounced /keər/, containing the centering diphthong /eə/.", 'diff': 'MEDIUM'}, {'q': "Identify the word that contains the short vowel sound /ʊ/ as in 'book':", 'a': 'foot', 'b': 'food', 'c': 'fool', 'd': 'boot', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Foot' has the short vowel /ʊ/, while 'food', 'fool', and 'boot' have the long vowel /u:/.", 'diff': 'MEDIUM'}, {'q': "In which of the following words is the suffix '-ed' pronounced as /t/?", 'a': 'walked', 'b': 'wanted', 'c': 'needed', 'd': 'played', 'ans': 'A', 'topic': 'Oral English', 'exp': "Following a voiceless consonant sound (/k/), the past tense suffix '-ed' is pronounced /t/ ('walked' /wɔ:kt/).", 'diff': 'MEDIUM'}, {'q': "In which of the following words is the suffix '-ed' pronounced as /ɪd/?", 'a': 'decided', 'b': 'laughed', 'c': 'begged', 'd': 'called', 'ans': 'A', 'topic': 'Oral English', 'exp': "When the base verb ends in /t/ or /d/, the '-ed' ending is pronounced as a separate syllable /ɪd/ ('decided' /dɪˈsaɪ.dɪd/).", 'diff': 'MEDIUM'}, {'q': "Which of the following words contains the consonant sound /ʒ/ as in 'measure'?", 'a': 'vision', 'b': 'mission', 'c': 'action', 'd': 'station', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Vision' contains the voiced palato-alveolar fricative /ʒ/, while the others have voiceless /ʃ/.", 'diff': 'MEDIUM'}, {'q': "Identify the word that contains the consonant sound /dʒ/ as in 'judge':", 'a': 'soldier', 'b': 'sugar', 'c': 'measure', 'd': 'pressure', 'ans': 'A', 'topic': 'Oral English', 'exp': "In 'soldier' (/ˈsəʊl.dʒər/), the 'di' cluster produces the voiced affricate /dʒ/.", 'diff': 'MEDIUM'}, {'q': "Choose the option that is nearest in meaning to the word 'admonish':", 'a': 'reprimand or scold gently', 'b': 'praise enthusiastically', 'c': 'reward generously', 'd': 'ignore completely', 'ans': 'A', 'topic': 'Vocabulary', 'exp': "'Admonish' means to warn or reprimand someone firmly or gently.", 'diff': 'MEDIUM'}, {'q': "Choose the word that has the same vowel sound as in 'sun':", 'a': 'son', 'b': 'soon', 'c': 'song', 'd': 'sour', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Son' /sʌn/ shares the identical short central vowel sound with 'sun' /sʌn/.", 'diff': 'MEDIUM'}, {'q': "Choose the word that has the same consonant sound as in 'cough':", 'a': 'laugh', 'b': 'dough', 'c': 'ghost', 'd': 'bough', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Laugh' ends in the voiceless labiodental fricative /f/, exactly matching 'cough'.", 'diff': 'MEDIUM'}, {'q': "Choose the word that rhymes with 'suite':", 'a': 'sweet', 'b': 'suit', 'c': 'sweat', 'd': 'shoot', 'ans': 'A', 'topic': 'Oral English', 'exp': "'Suite' is pronounced /swi:t/ and rhymes with 'sweet'.", 'diff': 'MEDIUM'}, {'q': "In the word 'REFUSE' (noun, meaning garbage), which syllable is stressed?", 'a': 'first syllable (REF-use)', 'b': 'second syllable (ref-USE)', 'c': 'both syllables', 'd': 'neither syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "The noun 'refuse' (waste) takes primary stress on the first syllable.", 'diff': 'MEDIUM'}, {'q': "In the word 'REFUSE' (verb, meaning to decline), which syllable is stressed?", 'a': 'second syllable (re-FUSE)', 'b': 'first syllable (RE-fuse)', 'c': 'both syllables', 'd': 'neither syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "The verb 'refuse' takes primary stress on the second syllable.", 'diff': 'MEDIUM'}, {'q': "In the word 'PRESENT' (noun, meaning gift), the primary stress falls on the:", 'a': 'first syllable', 'b': 'second syllable', 'c': 'both syllables', 'd': 'neither syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "The noun 'present' takes initial stress ('PRE-sent').", 'diff': 'MEDIUM'}, {'q': "In the word 'PRESENT' (verb, meaning to bestow or show), the primary stress falls on the:", 'a': 'second syllable', 'b': 'first syllable', 'c': 'both syllables', 'd': 'neither syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "The verb 'present' takes ultimate stress ('pre-SENT').", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in 'POLITICIAN'?", 'a': 'third syllable (pol-i-TI-cian)', 'b': 'first syllable', 'c': 'second syllable', 'd': 'fourth syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-cian' take primary stress on the penultimate syllable.", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in 'ECONOMIC'?", 'a': 'third syllable (ec-o-NOM-ic)', 'b': 'first syllable', 'c': 'second syllable', 'd': 'fourth syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-ic' take stress on the syllable preceding the suffix.", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in 'BIOLOGY'?", 'a': 'second syllable (bi-OL-o-gy)', 'b': 'first syllable', 'c': 'third syllable', 'd': 'fourth syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-ology' take stress on the antepenultimate syllable.", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in 'GEOGRAPHY'?", 'a': 'second syllable (ge-OG-ra-phy)', 'b': 'first syllable', 'c': 'third syllable', 'd': 'fourth syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-graphy' take stress on the antepenultimate syllable.", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in 'SUPERIORITY'?", 'a': 'fourth syllable (su-pe-ri-OR-i-ty)', 'b': 'first syllable', 'c': 'second syllable', 'd': 'third syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-ity' take stress on the antepenultimate syllable (su-pe-ri-OR-i-ty).", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in 'CIVILIZATION'?", 'a': 'fifth syllable (civ-i-li-ZA-tion)', 'b': 'first syllable', 'c': 'second syllable', 'd': 'third syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-tion' take primary stress on the penultimate syllable.", 'diff': 'MEDIUM'}, {'q': "Which syllable receives primary stress in 'ORGANIZATION'?", 'a': 'fifth syllable (or-gan-i-ZA-tion)', 'b': 'first syllable', 'c': 'second syllable', 'd': 'third syllable', 'ans': 'A', 'topic': 'Stress Patterns', 'exp': "Words ending in '-tion' take primary stress on the penultimate syllable.", 'diff': 'MEDIUM'}, {'q': 'The students were advised to steer clear _______ bad company in the school hostel.', 'a': 'of', 'b': 'from', 'c': 'with', 'd': 'against', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The idiom 'to steer clear of' means to avoid something or someone.", 'diff': 'MEDIUM'}, {'q': 'He took exception _______ the derogatory remarks made about his ethnic background.', 'a': 'to', 'b': 'against', 'c': 'with', 'd': 'from', 'ans': 'A', 'topic': 'Prepositions', 'exp': "The idiom 'to take exception to' means to object to or be offended by something.", 'diff': 'MEDIUM'}, {'q': 'She burst into tears at the drop of a _______, surprising everyone in the room.', 'a': 'hat', 'b': 'coin', 'c': 'pin', 'd': 'cup', 'ans': 'A', 'topic': 'Idioms', 'exp': "'At the drop of a hat' means without hesitation or for the slightest reason.", 'diff': 'MEDIUM'}, {'q': 'The new general manager vowed to turn over a new _______ regarding staff welfare.', 'a': 'leaf', 'b': 'page', 'c': 'book', 'd': 'branch', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To turn over a new leaf' means to behave in a better or more responsible way.", 'diff': 'MEDIUM'}, {'q': 'The police officer caught the burglar red-_______ inside the bank vault.', 'a': 'handed', 'b': 'legged', 'c': 'footed', 'd': 'headed', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To catch someone red-handed' means to discover someone in the act of committing a crime.", 'diff': 'MEDIUM'}, {'q': 'He passed the competitive civil service entrance exam with flying _______. ', 'a': 'colors', 'b': 'flags', 'c': 'kites', 'd': 'banners', 'ans': 'A', 'topic': 'Idioms', 'exp': "'With flying colors' means with great victory, distinction, or success.", 'diff': 'MEDIUM'}, {'q': 'The corrupt accountant tried to pull the _______ over the auditor eyes.', 'a': 'wool', 'b': 'cloth', 'c': 'sheet', 'd': 'hat', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To pull the wool over someone's eyes' means to deceive someone in order to prevent them from discovering the truth.", 'diff': 'MEDIUM'}, {'q': 'She decided to burn the _______ oil studying for the West African Senior School Certificate Examination.', 'a': 'midnight', 'b': 'evening', 'c': 'morning', 'd': 'night', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To burn the midnight oil' means to work or study late into the night.", 'diff': 'MEDIUM'}, {'q': 'The speaker hit the _______ on the head when he analyzed the causes of youth restiveness.', 'a': 'nail', 'b': 'hammer', 'c': 'peg', 'd': 'target', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To hit the nail on the head' means to describe exactly what is causing a situation or problem.", 'diff': 'MEDIUM'}, {'q': 'Winning the championship title was a feather in his _______.', 'a': 'cap', 'b': 'hat', 'c': 'shirt', 'd': 'hair', 'ans': 'A', 'topic': 'Idioms', 'exp': "'A feather in one's cap' is an achievement or honor to be proud of.", 'diff': 'MEDIUM'}, {'q': 'His rude comment really rubbed her the _______ way.', 'a': 'wrong', 'b': 'bad', 'c': 'hard', 'd': 'rough', 'ans': 'A', 'topic': 'Idioms', 'exp': "'To rub someone the wrong way' means to irritate, annoy, or bother someone.", 'diff': 'MEDIUM'}]
